func TestAOneCharacterQueryShowsSkippedNotRefused(t *testing.T) {
	hub, hubRequests := fakeHub(t)
	priv, _ := catalogServer(t, "api", "alpha")
	withImageSearcher(t, wiredLikeProduction(hub))

